import React, { useEffect, useState } from "react";
import axios from "axios";

const Results = () => {
  const [results, setResults] = useState([]);

  useEffect(() => {
    fetchResults();
  }, []);

  const fetchResults = async () => {
    try {
      const res = await axios.get("http://localhost:5000/results");
      setResults(res.data || []);
    } catch (err) {
      console.error("Error fetching results", err);
      setResults([]);
    }
  };

  const openCandidateDetail = (index) => {
    window.location.href = `/candidate/${index}`;
  };

  return (
    <div className="container mt-4">
      <h3 className="mb-4">Candidate Results</h3>

      {results.length === 0 && (
        <p className="text-muted">No results available.</p>
      )}

      {results.map((r, idx) => (
        <div className="card mb-3 shadow-sm" key={idx}>
          <div className="card-body">
            {/* Candidate Name (Clickable) */}
            <h5
              className="card-title text-primary"
              style={{ cursor: "pointer" }}
              onClick={() => openCandidateDetail(idx)}
            >
              {r.filename || `Candidate ${idx + 1}`}
            </h5>

            {/* Score */}
            <p>
              <strong>Score:</strong> {r.final_score}%
            </p>

            {/* Decision */}
            <p>
              <strong>Status:</strong>{" "}
              <span
                className={
                  r.decision === "Shortlisted"
                    ? "text-success fw-bold"
                    : r.decision === "Review Later"
                      ? "text-warning fw-bold"
                      : "text-danger fw-bold"
                }
              >
                {r.decision}
              </span>
            </p>

            {/* Mandatory Skills */}
            {r.rules?.mandatory_skills && (
              <p>
                <strong>Mandatory Skills:</strong>{" "}
                {r.rules.mandatory_skills.status === "pass"
                  ? "Passed"
                  : "Failed"}
              </p>
            )}

            {/* Missing Mandatory Skills */}
            {r.rules?.mandatory_skills?.missing?.length > 0 && (
              <div>
                <strong className="text-danger">
                  Missing Mandatory Skills:
                </strong>
                <ul>
                  {r.rules.mandatory_skills.missing.map((skill, i) => (
                    <li key={i}>{skill}</li>
                  ))}
                </ul>
              </div>
            )}

            {/* Skill Match */}
            {r.rules?.skill_overlap && (
              <p>
                <strong>Skill Match:</strong> {r.rules.skill_overlap.score}%
              </p>
            )}

            {/* GitHub */}
            {r.rules?.github && (
              <p>
                <strong>GitHub:</strong>{" "}
                {r.rules.github.status === "pass" ? "Provided" : "Not Provided"}
              </p>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

export default Results;
